#!/usr/bin/env python3
# Generated By: Claude Code (Claude Sonnet 4.5)
"""
Merge Claude Code settings.json files intelligently.

Merges repo settings into global settings with conflict detection.
Arrays are merged (union), objects are deep merged, scalar conflicts fail.
"""

import json
import sys
from pathlib import Path
from typing import Any, Dict, List, Tuple


def merge_settings(repo_settings: Dict[str, Any], global_settings: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """
    Merge repo settings into global settings.

    Returns:
        Tuple of (merged_settings, conflicts)
    """
    conflicts = []
    merged = global_settings.copy()

    def deep_merge(path: str, repo_value: Any, global_value: Any) -> Any:
        """Recursively merge values, tracking conflicts."""

        # If types differ, that's a conflict
        if type(repo_value) != type(global_value):
            conflicts.append(
                f"{path}: Type mismatch - repo has {type(repo_value).__name__}, "
                f"global has {type(global_value).__name__}"
            )
            return global_value

        # Merge lists by taking union
        if isinstance(repo_value, list):
            merged_list = global_value.copy()
            for item in repo_value:
                if item not in merged_list:
                    merged_list.append(item)
            return merged_list

        # Merge dicts recursively
        if isinstance(repo_value, dict):
            merged_dict = global_value.copy()
            for key, value in repo_value.items():
                current_path = f"{path}.{key}" if path else key
                if key in merged_dict:
                    merged_dict[key] = deep_merge(current_path, value, merged_dict[key])
                else:
                    merged_dict[key] = value
            return merged_dict

        # For scalars, conflict if values differ
        if repo_value != global_value:
            conflicts.append(
                f"{path}: Value conflict - repo has {repr(repo_value)}, "
                f"global has {repr(global_value)}"
            )
            return global_value

        return repo_value

    # Merge top-level keys
    for key, value in repo_settings.items():
        if key in merged:
            merged[key] = deep_merge(key, value, merged[key])
        else:
            merged[key] = value

    return merged, conflicts


def main():
    if len(sys.argv) != 3:
        print("Usage: merge_claude_settings.py <repo_settings.json> <global_settings.json>", file=sys.stderr)
        sys.exit(1)

    repo_path = Path(sys.argv[1])
    global_path = Path(sys.argv[2])

    # Load repo settings
    if not repo_path.exists():
        print(f"ERROR: Repo settings file not found: {repo_path}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(repo_path) as f:
            repo_settings = json.load(f)
    except json.JSONDecodeError as e:
        print(f"ERROR: Invalid JSON in repo settings: {e}", file=sys.stderr)
        sys.exit(1)

    # Load global settings (if exists)
    if global_path.exists():
        try:
            with open(global_path) as f:
                global_settings = json.load(f)
        except json.JSONDecodeError as e:
            print(f"ERROR: Invalid JSON in global settings: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        # No global settings yet, use repo settings as-is
        global_settings = {}

    # Merge settings
    merged, conflicts = merge_settings(repo_settings, global_settings)

    # If conflicts exist, fail without making changes
    if conflicts:
        print("ERROR: Cannot merge settings due to conflicts:", file=sys.stderr)
        for conflict in conflicts:
            print(f"  - {conflict}", file=sys.stderr)
        print("\nGlobal settings were NOT modified.", file=sys.stderr)
        print("Resolve conflicts manually or update repo settings to match global settings.", file=sys.stderr)
        sys.exit(1)

    # Write merged settings atomically
    temp_path = global_path.with_suffix('.json.tmp')
    try:
        with open(temp_path, 'w') as f:
            json.dump(merged, f, indent=2)
            f.write('\n')
        temp_path.replace(global_path)
        print(f"Successfully merged settings to {global_path}")
    except Exception as e:
        print(f"ERROR: Failed to write merged settings: {e}", file=sys.stderr)
        if temp_path.exists():
            temp_path.unlink()
        sys.exit(1)


if __name__ == '__main__':
    main()
